{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret indeholder flere juridiske fejl i forhold til kilderne. Det kræver, at dokumentationen er skrevet af en læge, der har undersøgt ansøgeren. Kilderne kræver journaler fra egen læge, speciallæge, hospital eller ambulant klinik. Det påstår en 6-måneders aktualitetsgrænse, som ikke findes i kilderne. Det henviser til et SU-styrelsen-skema, som kilderne ikke nævner. Det angiver 'hjælpemidler' som indhold, hvilket heller ikke er i kilderne."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Svaret nævner ikke diagnose (hvis stillet), udrednings- og sygdomsforløb, planlagt behandling, erhvervsevne (hvis muligt), den varige funktionsnedsættelses art og grad, eller at oplysningerne skal fremsendes, når de er tilgængelige i journalen. Det dækker kun funktionspåvirkning og behandling delvist."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret forsøger at besvare, hvad den lægelige dokumentation skal beskrive, og forbliver på emnet, selv om indholdet er delvist forkert."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde som lov, bekendtgørelse eller vejledning. Der er kun en generisk henvisning til SU-styrelsens hjemmeside for et skema."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen identificerbar kilde er angivet, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så støtten mellem påstand og kilde kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer uunderstøttede krav: en 6-måneders grænse for aktualitet, krav om at en læge har undersøgt ansøgeren, et særligt SU-styrelsesskema og hjælpemidler som indhold. Intet af dette findes i materialet."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Svaret mangler forbeholdene 'hvis diagnose er stillet', 'hvis planlagt' og 'hvis muligt', og at oplysninger skal fremsendes, når de er tilgængelige. Aktualitet er erstattet af en fast, ikke-understøttet tidsgrænse."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er internt sammenhængende, og konklusionen følger af de opstillede punkter, selv om punkterne delvist er forkerte."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret gør vejledningens og bekendtgørelsens regler mere absolutte eller opfinder nye: 'skal være skrevet af en læge' og 'ikke ældre end 6 måneder'. Samtidig svækkes 'skal' om fremsendelse af tilgængelige oplysninger, fordi det slet ikke nævnes."}
  },
  "xhaile_coverage": {
    "A39": {"label": "no", "reason": "Diagnose (hvis stillet) nævnes ikke. Svaret taler kun om 'sygdomme eller skader'."},
    "A41": {"label": "partial", "reason": "Svaret beskriver sygdomme eller skader og deres påvirkning, men nævner ikke sygdomsforløbet eller udredningsforløbet."},
    "A42": {"label": "partial", "reason": "Svaret nævner 'behandlinger eller hjælpemidler du har brug for', men ikke behandlingsforløbet eller den behandling, patienten får."},
    "A45": {"label": "no", "reason": "Planlagt behandling (hvis der er planlagt en) nævnes ikke. 'Behandlinger du har brug for' svarer ikke til planlagt behandling."},
    "A47": {"label": "no", "reason": "Påvirkning af erhvervsevnen (hvis muligt) nævnes ikke. Svaret nævner kun 'funktionsevne og daglig livsførelse'."}
  },
  "overall_notes": "Svaret er generisk og uden kilder. Det rammer dagligt funktionsniveau, men udelader flere kritiske elementer og forbehold. Det tilføjer uunderstøttede regler (6 måneder, skema, lægekrav, hjælpemidler)."
}

